// Based on hardware schematic\n\n// Define button pins according to schematic\nconst int BUTTON_KEY0 = 3;   // KEY0 - GPIO3\nconst int BUTTON_KEY1 = 4;   // KEY1 - GPIO4\nconst int BUTTON_KEY2 = 5;   // KEY2 - GPIO5\n\n// Button state variables\nbool lastKey0State = HIGH;\nbool lastKey1State = HIGH;\nbool lastKey2State = HIGH;\n\nvoid setup() {\n  // Initialize serial communication\n  Serial1.begin(115200, SERIAL_8N1, 44, 43);\n  while (!Serial1) {\n    delay(10); // Wait for serial port to connect\n  }\n  \n  Serial1.println("=================================");\n  Serial1.println("reTerminal E Series - Button Test");\n  Serial1.println("=================================");\n  Serial1.println("Press any button to see output");\n  Serial1.println();\n  \n  // Configure button pins as inputs\n  // Hardware already has pull-up resistors, so use INPUT mode\n  pinMode(BUTTON_KEY0, INPUT);\n  pinMode(BUTTON_KEY1, INPUT);\n  pinMode(BUTTON_KEY2, INPUT);\n  \n  // Read initial states\n  lastKey0State = digitalRead(BUTTON_KEY0);\n  lastKey1State = digitalRead(BUTTON_KEY1);\n  lastKey2State = digitalRead(BUTTON_KEY2);\n  \n  Serial1.println("Setup complete. Ready to detect button presses...");\n}\n\nvoid loop() {\n  // Read current button states\n  bool key0State = digitalRead(BUTTON_KEY0);\n  bool key1State = digitalRead(BUTTON_KEY1);\n  bool key2State = digitalRead(BUTTON_KEY2);\n  \n  // Check KEY0\n  if (key0State != lastKey0State) {\n    if (key0State == LOW) {\n      Serial1.println("KEY0 (GPIO3) pressed!");\n    } else {\n      Serial1.println("KEY0 (GPIO3) released!");\n    }\n    lastKey0State = key0State;\n    delay(50); // Debounce delay\n  }\n  \n  // Check KEY1\n  if (key1State != lastKey1State) {\n    if (key1State == LOW) {\n      Serial1.println("KEY1 (GPIO4) pressed!");\n    } else {\n      Serial1.println("KEY1 (GPIO4) released!");\n    }\n    lastKey1State = key1State;\n    delay(50); // Debounce delay\n  }\n  \n  // Check KEY2\n  if (key2State != lastKey2State) {\n    if (key2State == LOW) {\n      Serial1.println("KEY2 (GPIO5) pressed!");\n    } else {\n      Serial1.println("KEY2 (GPIO5) released!");\n    }\n    lastKey2State = key2State;\n    delay(50); // Debounce delay\n  }\n  \n  delay(10); // Small delay to prevent excessive CPU usage\n}\n'})}),"\n",(0,l.jsx)(n.p,{children:(0,l.jsx)(n.strong,{children:"\u30B3\u30FC\u30C9\u306E\u52D5\u4F5C\u539F\u7406\uFF1A"})}),"\n",(0,l.jsxs)(n.ol,{children:["\n",(0,l.jsxs)(n.li,{children:["\n",(0,l.jsxs)(n.p,{children:[(0,l.jsx)(n.strong,{children:"\u30D4\u30F3\u5B9A\u7FA9"}),": \u5404\u30DC\u30BF\u30F3\u306EGPIO\u30D4\u30F3\u756A\u53F7\u306E\u5B9A\u6570\u3092\u5B9A\u7FA9\u3057\u307E\u3059\u3002"]}),"\n"]}),"\n",(0,l.jsxs)(n.li,{children:["\n",(0,l.jsxs)(n.p,{children:[(0,l.jsx)(n.strong,{children:"\u30D4\u30F3\u8A2D\u5B9A"}),": ",(0,l.jsx)(n.code,{children:"setup()"}),"\u3067\u3001\u5404\u30DC\u30BF\u30F3\u30D4\u30F3\u3092",(0,l.jsx)(n.code,{children:"INPUT"}),"\u3068\u3057\u3066\u8A2D\u5B9A\u3057\u307E\u3059\u3002"]}),"\n"]}),"\n",(0,l.jsxs)(n.li,{children:["\n",(0,l.jsxs)(n.p,{children:[(0,l.jsx)(n.strong,{children:"\u30DC\u30BF\u30F3\u691C\u51FA"}),": ",(0,l.jsx)(n.code,{children:"loop()"}),"\u3067\u3001",(0,l.jsx)(n.code,{children:"digitalRead()"}),"\u3092\u4F7F\u7528\u3057\u3066\u5404\u30DC\u30BF\u30F3\u306E\u72B6\u614B\u3092\u7D99\u7D9A\u7684\u306B\u30C1\u30A7\u30C3\u30AF\u3057\u307E\u3059\u3002\u30DC\u30BF\u30F3\u304C\u62BC\u3055\u308C\u308B\u3068\u3001\u30D4\u30F3\u306FLOW\u3092\u8AAD\u307F\u53D6\u308A\u307E\u3059\u3002"]}),"\n"]}),"\n",(0,l.jsxs)(n.li,{children:["\n",(0,l.jsxs)(n.p,{children:[(0,l.jsx)(n.strong,{children:"\u30C7\u30D0\u30A6\u30F3\u30B9"}),": \u5404\u30DC\u30BF\u30F3\u62BC\u4E0B\u5F8C\u306E200ms\u306E\u7C21\u5358\u306A\u9045\u5EF6\u306B\u3088\u308A\u3001\u6A5F\u68B0\u7684\u306A\u30D0\u30A6\u30F3\u30B9\u306B\u3088\u308B\u5358\u4E00\u62BC\u4E0B\u304B\u3089\u306E\u8907\u6570\u691C\u51FA\u3092\u9632\u304E\u307E\u3059\u3002"]}),"\n"]}),"\n",(0,l.jsxs)(